// Generated from data/*.json by backend/bundle-content.mjs.
export const bundledData={"schemaVersion":1,"isDemo":true,"profile":{"name":"Nguyễn Hoàng Việt","meta":"Ngôn ngữ · Dữ liệu · Đổi mới sáng tạo","headline":["Nguyễn","Hoàng Việt."],"intro":"Chào bạn, mình là Việt — hơi nhiều câu hỏi, khá nhiều chuyện để kể.\nHọc ngôn ngữ, mê dữ liệu, và thích làm những điều có ích cùng mọi người.","aboutTitle":["Một chiếc Việt,","nhiều chế độ."],"about":"Mình học Tiếng Anh thương mại và Tài chính quốc tế ở Đại học Ngoại thương. Có hôm mình đọc nghiên cứu, có hôm ngồi gỡ một bảng dữ liệu, có hôm lại lo cho một chương trình chạy đúng nhịp. Nghe hơi nhiều tab đang mở nhỉ? Điểm chung là mình muốn hiểu cho đúng, kể cho dễ hiểu và làm cho đến nơi. Research mode hay đời thường mode, vẫn là chiếc Việt thích hỏi “vì sao?”.","portrait":{"type":"image","url":"./assets/photos/placement-11.webp","driveFileId":"1_--q_bu-X3QKB3BV1vardacER_recUPD","alt":"Về tôi 01","fit":"cover","position":"50% 50%"},"values":[{"title":"Tò mò có căn cứ","detail":"Hỏi “vì sao?”, rồi đọc nguồn và kiểm tra dữ liệu."},{"title":"Viết cho người đọc","detail":"Tiếng Việt rõ ý, tiếng Anh đúng sắc thái, thông điệp đến đúng người."},{"title":"Cùng làm cho tới nơi","detail":"Chốt việc rõ ràng, giữ nhịp đội nhóm, lắng nghe khi cần đổi hướng."}],"email":"","links":[],"contactIntro":"Bạn có một đề tài cần đào sâu, một bảng dữ liệu hơi khó ở, hay một dự án đang tìm người cùng làm? Mình thích những cuộc trò chuyện bắt đầu bằng “hay là mình thử…”. Say hello — biết đâu lại có một chặng mới để kể!"},"fields":[{"id":"school","title":"Đi học, mang về cả rổ câu hỏi.","label":"FOREIGN TRADE UNIVERSITY / HÀ NỘI","description":"Khởi đầu với Tiếng Anh thương mại, rồi học thêm Tài chính quốc tế: mình đang mở thêm “cửa sổ” để nhìn cùng một vấn đề. Ngôn ngữ giúp mình đọc xa hơn; tài chính và dữ liệu kéo mình về câu hỏi rất thực tế: điều này có cơ sở không? Bài vở có thể hết trang, chứ danh sách câu hỏi thì… chưa chắc.","points":[],"art":"research","media":{"type":"image","url":"./assets/photos/placement-18.webp","driveFileId":"1larMR3gtS7cJtfVCEa46o2dHl0Mqycvt","alt":"Trường học 01","fit":"cover","position":"50% 56%"}}],"chapters":[{"id":"community","title":"Làm nội dung: bớt đoán, chịu khó nghe.","period":"Vietnam Volunteer Network","summary":"Ở Vietnam Volunteer Network, mình dẫn nhóm phân tích dữ liệu và tổ chức lại nội dung. Bắt đầu bằng dữ liệu ba tháng đầu, Meta Business Suite và khảo sát nội bộ, cả nhóm tìm xem người đọc thực sự quan tâm điều gì. Ý tưởng vẫn cần sáng tạo; chỉ là mình muốn nó có chỗ đứng ngoài cảm giác “chắc sẽ hay”.","tags":["Dữ liệu","Cộng đồng"],"milestones":[{"label":"Khoan lên lịch, nghe nhau đã.","text":"Dẫn nhóm hơn 15 thành viên, mình cùng mọi người sắp xếp nội dung thành ba tuyến. Câu hỏi cũng đổi từ “tuần này đăng gì?” sang “người đọc đang cần gì ở cộng đồng này?”. Một thay đổi nhỏ trong cách hỏi, nhưng giúp cả nhóm biết mình đang viết cho ai."},{"label":"Có số liệu rồi, kể chuyện tiếp thôi.","text":"Tương tác tăng 1.500% và có thêm 80.000 người theo dõi trong hai tháng. Những con số ấy đi cùng việc đọc tín hiệu từ dữ liệu, điều chỉnh nội dung và giữ cả nhóm làm việc nhất quán. Good teamwork — thành quả để kể, và cả quá trình để học."}],"media":{"type":"image","url":"./assets/photos/2x1a1544.jpeg.webp","alt":"Nhóm bạn trước một cánh cửa lớn","caption":"Kinh nghiệm đi làm · Ảnh được Việt chọn cho bản demo","fit":"cover","position":"50% 60%"}},{"id":"sustainability","title":"Đọc ESG, viết sao cho người ta hiểu.","period":"Trung tâm Đổi mới sáng tạo & Ươm tạo FTU","summary":"Tại Trung tâm Đổi mới sáng tạo & Ươm tạo FTU, mình thực tập truyền thông và nghiên cứu, đọc tài liệu Việt–Anh về ESG, Net Zero và chính sách CO₂. Nhiệm vụ không chỉ là biết thuật ngữ, mà còn phải giải thích đúng để người đọc theo được. Đọc sâu, viết rõ — nghe gọn vậy thôi, làm thì khá nhiều vòng.","tags":["ESG","Nghiên cứu"],"milestones":[{"label":"Nhiều tab tài liệu, một luận điểm rõ.","text":"Mình đã thực hiện hơn 15 bài nghiên cứu, dành khoảng 48 giờ cho mỗi bài. Đọc xong chưa có nghĩa là viết được ngay: mình còn chọn luận điểm, đối chiếu nguồn và tìm cách diễn đạt. Từ một màn hình nhiều tab đến một bài viết có đường đi rõ ràng — đó là phần việc mình tập làm tốt hơn."},{"label":"Bấm đăng rồi, vẫn chưa hết việc.","text":"Mình theo dõi hiệu quả nội dung, tổng hợp báo cáo và đề xuất điều chỉnh cho lãnh đạo trung tâm. Phản hồi giúp mình biết đoạn nào rõ, chỗ nào còn khó hiểu và lần sau nên đổi gì. Publish, learn, revise — viết xong là bắt đầu một vòng học mới."}],"media":{"type":"image","url":"./assets/photos/placement-20.webp","driveFileId":"1rWRbpDXZivhzqZir8r70jcEgKAPrf3x9","alt":"Kinh nghiệm FIIS","fit":"cover","position":"50% 60%"}},{"id":"business","title":"Đi bán hàng, học cách nghe cho đúng.","period":"Đồng Phục Hải Anh","summary":"Ở Đồng Phục Hải Anh, công việc B2B/B2C giúp mình gặp những nhu cầu rất cụ thể: khách cần gì, lo gì, và mình có thể đáp ứng đến đâu? Giao tiếp hay không chỉ nằm ở lời nói. Nó còn nằm ở việc hiểu đúng yêu cầu và giữ lời bằng một quy trình làm việc tử tế.","tags":["Kinh doanh","Khách hàng"],"milestones":[{"label":"Chốt đơn bắt đầu từ… chưa vội chốt.","text":"Mình tư vấn hơn 30 khách hàng, chốt hơn 15 đơn với tổng giá trị trên 100 triệu đồng và vào Top 5 doanh thu trong một tháng. Điều mình học nhiều nhất là nghe nhu cầu phía sau câu hỏi ban đầu. Hỏi rõ trước, tư vấn sát sau — đôi bên đều dễ làm việc hơn.","media":{"type":"image","url":"./assets/photos/placement-08.webp","driveFileId":"1lTvGfcrXH00u6ZRKFZhQKIMZkjsZiOVz","alt":"Kinh nghiệm Đồng phục Hải anh 01","fit":"cover","position":"50% 50%"}},{"label":"Nhận việc rồi, theo đến cuối nhé.","text":"Quản lý đơn hàng đầu cuối, báo cáo doanh thu tháng và duy trì tỷ lệ hài lòng trên 90%. Sau một cuộc trao đổi tốt vẫn còn lịch giao, tiến độ và những chi tiết phải nhớ. Follow-through — nói được, rồi làm cho tới nơi.","media":{"type":"image","url":"./assets/photos/placement-07.webp","driveFileId":"1q0EVzLHWiBQhvG6tQdadJOZCmfvwqHav","alt":"Kinh nghiệm Đồng phục Hải anh 02","fit":"cover","position":"50% 50%"}}],"media":{"type":"image","url":"./assets/photos/placement-08.webp","driveFileId":"1lTvGfcrXH00u6ZRKFZhQKIMZkjsZiOVz","alt":"Kinh nghiệm Đồng phục Hải anh 01","fit":"cover","position":"50% 50%"}},{"id":"coordination","title":"Giữ nhịp chương trình, kết nối mọi người.","period":"NIC × Dassault Systèmes","summary":"Trong chương trình NIC × Dassault Systèmes, mình điều phối đào tạo Agile/Scrum khoảng ba tháng, theo sprint hai tuần. Học viên, doanh nghiệp và chuyên gia có những kỳ vọng khác nhau; công việc của mình là giúp mọi người biết đang đi đâu và cần phối hợp thế nào. Lịch có nhịp, người cũng cần được nghe.","tags":["Agile/Scrum","Điều phối"],"milestones":[{"label":"Hai tuần một sprint, từng việc một nhịp.","text":"Chương trình có hơn 40 học viên, hơn 7 doanh nghiệp đối tác và tỷ lệ hoàn thành/đạt chuẩn tốt nghiệp 90%. Mình phối hợp với doanh nghiệp, kỹ sư và chuyên gia để nội dung sát nhu cầu thực tế. Một chương trình chạy tốt cần cả lịch rõ lẫn sự phối hợp đều đặn."},{"label":"Landing page: lời chào đầu tiên cũng cần chăm.","text":"Mình tự thiết kế landing page và tài liệu truyền thông; đạt tỷ lệ đăng ký 67% và lưu lượng quốc tế 30%. Người xem cần biết chương trình dành cho ai, đem lại gì và đăng ký thế nào. Viết rõ, thiết kế dễ dùng, rồi đo hiệu quả — mỗi phần giúp lời chào đầu tiên có ích hơn."}],"media":{"type":"image","url":"./assets/photos/2x1a1544.jpeg.webp","alt":"Nhóm bạn trước một cánh cửa lớn","caption":"Kinh nghiệm đi làm · Ảnh được Việt chọn cho bản demo","fit":"cover","position":"50% 60%"}},{"id":"ai-research","title":"Hỏi chuyện AI, trả lời bằng nghiên cứu.","period":"Chủ nhiệm đề tài nghiên cứu sinh viên FTU","summary":"Chatbot có thể đóng vai trò gì trong những cuộc trò chuyện về cảm xúc? Mình cùng nhóm đưa câu hỏi ấy vào nghiên cứu định lượng với 365 sinh viên. Hào hứng với một chủ đề mới là khởi đầu; chọn cách đo và đọc kết quả cẩn thận mới giúp câu chuyện có cơ sở.","tags":["AI","SPSS"],"milestones":[{"label":"Từ “mình tò mò” đến một mô hình.","text":"Nhóm thiết kế khảo sát, kiểm định độ tin cậy, EFA và hồi quy đa biến. Tính hữu ích thực tế là yếu tố dự báo mạnh nhất cho ý định tiếp tục sử dụng; mô hình giải thích 43,9% phương sai. Kết quả giúp trả lời một phần câu hỏi — và cũng nhắc mình phải nói rõ giới hạn của cách đo."},{"label":"Có kết quả rồi, lại muốn hỏi thêm.","text":"Đề tài được đánh giá 77/85 khi nộp giải thưởng nghiên cứu sinh viên năm 2026. Mình giữ cả kết quả lẫn những điều chưa biết: mẫu khảo sát phản ánh đến đâu, còn thiếu góc nhìn nào, lần tới nên kiểm tra gì? Research mode: câu hỏi tiếp theo vẫn đang chờ."}],"media":{"type":"image","url":"./assets/photos/2x1a1544.jpeg.webp","alt":"Nhóm bạn trước một cánh cửa lớn","caption":"Kinh nghiệm đi làm · Ảnh được Việt chọn cho bản demo","fit":"cover","position":"50% 60%"}}],"projects":[{"id":"city-notes","title":"Ra phố hít thở, não vẫn hỏi “vì sao?”.","fieldId":"life","coverWord":"City notes.","summary":"Định đi dạo cho đầu nhẹ chút, ai dè mang theo cả câu hỏi về thành phố. Một câu chuyện demo của chiếc Việt thích quan sát.","sections":[{"title":"Đi dạo thôi mà, sao lại nghĩ bài?","text":"Trong câu chuyện demo này, mình gập máy sau một buổi đọc về Net Zero rồi ra phố. Đến trạm xe buýt, mình thấy người đứng dưới bóng cây, người nép cạnh biển quảng cáo để tìm chút mát. Não lập tức bật một tab mới: không gian này có dễ chịu với tất cả mọi người không? Đi dạo mà cũng phát sinh câu hỏi — chịu chiếc đầu này thật."},{"title":"Ghi chú nhỏ, chưa kết luận to.","text":"Mình ghi ba điều: ở đây có gì, ai đang dùng, ai còn gặp khó khăn. Vài quan sát chưa đủ để kết luận về cả thành phố, nhưng đủ để mình nhìn kỹ hơn. ESG bỗng gần hơn một chút: nó có thể bắt đầu từ chuyện ai được đứng mát trong lúc chờ xe."},{"title":"Mang về một tấm ảnh, thêm vài câu hỏi.","text":"Buổi đi bộ tưởng tượng không kết thúc bằng một giải pháp hoành tráng. Chỉ có ảnh, ghi chú và lời nhắc: học khái niệm lớn cũng đừng bỏ qua chuyện nhỏ. Touch grass, take notes — ra ngoài một chút, đầu lại có chuyện để kể."}],"chapterId":"","demoStory":true,"media":{"type":"image","url":"./assets/photos/placement-17.webp","driveFileId":"1Q1DGyb6qIgPKuWsv_wjOWCKkQWwTgMLU","alt":"Ngoài lề 01","fit":"cover","position":"50% 50%"},"gallery":[{"type":"image","url":"./assets/photos/placement-06.webp","driveFileId":"1UkDByXVdDVDBuY4cSQNrshkvc-SdDJnj","alt":"Ngoài lề bonus","fit":"cover","position":"50% 50%"}],"links":[]},{"id":"two-languages","title":"Một ý tưởng, hai ngôn ngữ, vài lần sửa.","fieldId":"notes","coverWord":"Between words.","summary":"Tiếng Anh viết một kiểu, tiếng Việt lại cần một nhịp khác. Mình thử giữ đúng ý mà vẫn để câu chữ có giọng riêng — trong một câu chuyện demo.","sections":[{"title":"Dịch sát quá, câu chữ hơi… cứng.","text":"Có những câu tiếng Anh dịch từng từ thì đúng mặt chữ, nhưng đọc bằng tiếng Việt lại nghe như đang mặc áo chưa vừa. Mình thử hỏi: người nói đang nhờ, gợi ý hay từ chối khéo? “That might be tricky” có lúc gần với “chỗ này hơi khó đấy” hơn là một câu về sự rắc rối. Ngữ cảnh quyết định sắc thái."},{"title":"Cùng một ý, thử vài cách kể.","text":"Trong bản demo này, mình thử viết cùng một ý cho bạn bè và cho người đọc một bài phân tích. Với bạn: “Để mình xem thêm nhé”. Trong bài viết: “Cần thêm dữ liệu để kết luận”. Ý chung là chưa vội chốt; cách nói đổi theo quan hệ và mục đích giao tiếp."},{"title":"Đổi tiếng, đừng đánh rơi giọng.","text":"Tiếng Việt có những chữ “nhé”, “ạ”, “mình”, “bạn” làm câu nói mềm đi hoặc đổi khoảng cách giữa người nói và người nghe. Tiếng Anh cũng có cách điều chỉnh độ trực tiếp riêng. Mình muốn dùng đúng lúc, đúng người — chứ không rắc tiếng Anh cho câu chữ có vẻ sang."}],"chapterId":"","demoStory":true,"media":{"type":"image","url":"./assets/photos/placement-16.webp","driveFileId":"1ZcvoP02r19zBxPxUYIE-eioVMJgVjHG9","alt":"Ngoài lề 02","fit":"cover","position":"50% 50%"},"gallery":[],"links":[]},{"id":"small-scripts","title":"Một việc lặp lại, một chiếc script cứu nguy.","fieldId":"moments","coverWord":"Small scripts.","summary":"Bảng tính hơi dài, thao tác hơi lặp. Trong câu chuyện demo này, mình rủ Python vào phụ một tay. Plot twist: máy cũng cần mình chỉ đúng.","sections":[{"title":"Copy, paste… rồi lại copy.","text":"Giả sử mình có một bảng tính với tên cột chưa đều, vài ô trống và một thao tác phải làm đi làm lại. Làm tay vẫn được, nhưng đến lần thứ mười thì đầu bắt đầu thương lượng: “Hay thử viết một đoạn script?”. Một ý tưởng nhỏ, xuất phát từ một việc hơi mỏi tay."},{"title":"Máy rất ngoan. Ngoan theo cả lỗi của mình.","text":"Mình viết thử bằng Python, chạy trên một mẫu nhỏ, rồi đối chiếu với kết quả làm tay. Có lỗi thì đọc thông báo và sửa từng chỗ. Máy không tự biết mình định làm gì; mình phải diễn đạt yêu cầu đủ rõ. Debugging cũng là một bài tập về sự kiên nhẫn."},{"title":"Bớt một việc lặp, thêm chút thời gian.","text":"Niềm vui trong câu chuyện này không phải làm ra công cụ to tát. Chỉ là bớt một thao tác lặp để dành thời gian cho phần cần suy nghĩ. Small script, happy human — một đoạn mã nhỏ, người dùng đỡ nhăn trán."}],"chapterId":"","demoStory":true,"media":{"type":"image","url":"./assets/photos/placement-15.webp","driveFileId":"1eVv88p8L-u-uMPyvptBSy4_Q_Z16I1U1","alt":"Ngoài lề 03","fit":"cover","position":"50% 50%"},"gallery":[],"links":[]},{"id":"behind-sprint","title":"Sprint có deadline. Người thì có tâm trạng.","fieldId":"life","coverWord":"Behind the sprint.","summary":"Một câu chuyện demo phía sau lịch họp và bảng tiến độ: đôi khi câu hỏi “bạn đang vướng gì?” có ích hơn một lời nhắc deadline.","sections":[{"title":"Họp xong rồi, còn một câu muốn hỏi.","text":"Trong cảnh kể chuyện này, cuộc họp kết thúc đúng giờ nhưng mình thấy có người vẫn ít nói. Bảng việc đã cập nhật, còn cảm giác của từng người thì chưa chắc. Mình thử hỏi riêng: “Có chỗ nào bạn đang vướng mà lúc nãy chưa tiện nói không?”."},{"title":"Từ “xong chưa?” sang “cần mình giúp gì?”.","text":"Hai câu đều có thể liên quan đến tiến độ, nhưng tạo cảm giác khác nhau. “Xong chưa?” kiểm tra trạng thái; “cần mình giúp gì?” mở đường cho người kia nói về khó khăn. Chọn câu nào còn tùy tình huống. Trong câu chuyện demo này, mình muốn bắt đầu bằng việc nghe."},{"title":"Giữ nhịp, cũng nhớ giữ người.","text":"Một sprint tốt cần mục tiêu rõ và trách nhiệm rõ. Mình còn muốn mọi người có thể nói sớm khi gặp vướng mắc. Teamwork nghe quen lắm, nhưng để làm được thì cần những cuộc trao đổi nhỏ, đều đặn và đủ chân thành."}],"chapterId":"","demoStory":true,"media":{"type":"image","url":"./assets/photos/placement-14.webp","driveFileId":"1zeZ1DGKnsYXFkXC0yYjnsqYp2kVhwt2q","alt":"Ngoài lề 04","fit":"cover","position":"50% 50%"},"gallery":[],"links":[]},{"id":"little-laughs","title":"Cho phép mình hơi ngốc nghếch một xíu.","fieldId":"life","chapterId":"","demoStory":true,"coverWord":"Just for fun.","summary":"Một chú thỏ, một chiếc meme, một khoảng nghỉ. Chiếc Việt không phải lúc nào cũng bật research mode đâu nha.","media":{"type":"image","url":"./assets/photos/placement-13.webp","driveFileId":"1b5Fcx4Bl0Iy_Tt8lpJyCgmk4hnPANa_q","alt":"Ngoài lề 05","fit":"cover","position":"50% 50%"},"gallery":[],"sections":[{"title":"Não xin nghỉ năm phút, được không?","text":"Có hôm mình muốn xem một hình hoạt họa vô lý một cách dễ thương rồi cười chút thôi. Không phân tích, không rút ra bài học ngay. Trong góc demo này, đó là một khoảng nghỉ nhỏ giữa các tab đang mở."},{"title":"Nghiêm túc làm việc, vui vẻ sống đời.","text":"Mình thích làm việc cẩn thận, nhưng cũng thích những chuyện chẳng cần thành tựu để được kể. Một ảnh buồn cười, một khoảnh khắc hơi ngố, một lời trêu đúng lúc. A little silly, a little happy — đời thường cũng có chỗ trên chiếc portfolio này."}],"links":[]}],"storyCategories":[{"id":"life","title":"Đời sống"},{"id":"moments","title":"Khoảnh khắc"},{"id":"notes","title":"Ghi chép"}],"demoNotice":"Bản demo · Một số góc nhìn và câu chuyện ngoài lề được sáng tác","subjourneys":{"fields":[{"id":"business-english","title":"Tiếng Anh mở cửa. Tiếng Việt giữ người đọc.","period":"Tiếng Anh thương mại, FTU","summary":"Đọc hiểu tiếng Anh là bước đầu; kể lại bằng tiếng Việt cho đúng và dễ hiểu mới là phần mình thích luyện. Một câu “You might want to…” không phải lúc nào cũng là “Bạn có thể muốn…”. Phải xem ai đang nói với ai, muốn gợi ý hay nhắc khéo, rồi mới chọn cách diễn đạt. Dịch ý, giữ giọng — challenge accepted.","media":{"type":"image","url":"./assets/photos/placement-18.webp","driveFileId":"1larMR3gtS7cJtfVCEa46o2dHl0Mqycvt","alt":"Trường học 01","fit":"cover","position":"50% 56%"}},{"id":"international-finance","title":"Học thêm tài chính, mở thêm một góc nhìn.","period":"Văn bằng hai Tài chính quốc tế, FTU","summary":"Từ ngôn ngữ sang Tài chính quốc tế, mình có thêm một bộ câu hỏi: dòng tiền đi đâu, doanh nghiệp được lợi gì, và một lựa chọn phải đánh đổi điều gì? Hai ngành học, một người học hơi tham. Nhưng càng học, mình càng thấy các góc nhìn có thể bổ sung cho nhau.","media":{"type":"image","url":"./assets/photos/placement-19.webp","driveFileId":"1vjC8oq2zithH9x6AJ0cl8ZiToT6a1uI6","alt":"Trường học 02","fit":"cover","position":"50% 55%"}},{"id":"learning-by-doing","title":"Học xong rồi… thử làm xem sao!","period":"Học qua nghiên cứu và thực hành","summary":"IELTS 7.5 là một cột mốc. Dữ liệu, Python và quản lý con người là những nhánh mình tiếp tục học thêm. Mình muốn đem kiến thức ra dùng: đọc một nguồn, phân tích một bảng số, viết một nội dung, rồi xem nó có giúp được việc gì. Learning by doing — vừa làm vừa biết mình còn thiếu gì.","children":[{"id":"research","title":"365 phản hồi, một câu hỏi không hề nhỏ.","period":"Đề tài nghiên cứu sinh viên FTU","summary":"Chatbot AI có thể hỗ trợ cảm xúc như thế nào? Mình dẫn dắt nghiên cứu với 365 sinh viên, dùng SPSS để kiểm định độ tin cậy, phân tích nhân tố khám phá (EFA) và hồi quy. Đặt câu hỏi thì hào hứng; biến câu hỏi thành thứ đo được mới cần kiên nhẫn. Sau cùng, kết quả vẫn phải được giải thích cho người đọc hiểu — chứ không chỉ để bảng số trông thật ngầu.","media":{"type":"image","url":"./assets/photos/placement-02.webp","driveFileId":"1J6IkSBRG4xGu4ks480KNgouxyReHlhaR","alt":"Trường học 03","fit":"cover","position":"50% 50%"}},{"id":"toolbox","title":"Balo kiến thức: thêm món, bớt bỡ ngỡ.","period":"Học thêm, dùng thêm","summary":"Google Data Analytics, IT Automation with Python, People Management Essentials và Python for Finance là các chứng chỉ. Mình học từng công cụ để xử lý dữ liệu gọn hơn, bớt việc lặp lại và hiểu cách làm việc cùng người khác. Balo hơi nặng thêm, nhưng lúc gặp việc mới thì đỡ “ủa, giờ sao ta?”.","media":{"type":"image","url":"./assets/photos/placement-02.webp","driveFileId":"1J6IkSBRG4xGu4ks480KNgouxyReHlhaR","alt":"Trường học 03","fit":"cover","position":"50% 50%"}}],"media":{"type":"image","url":"./assets/photos/placement-02.webp","driveFileId":"1J6IkSBRG4xGu4ks480KNgouxyReHlhaR","alt":"Trường học 03","fit":"cover","position":"50% 50%"}}],"about":[{"id":"curiosity","title":"Mình có một thói quen: hỏi thêm một câu.","period":"Góc nhìn demo · Diễn giải từ nền tảng nghiên cứu","summary":"Một con số tăng vọt? Một ý tưởng nghe rất thuyết phục? Mình thường hỏi thêm: nguồn ở đâu, đang đo điều gì, còn cách giải thích nào khác không? Tò mò có hơi tốn thời gian, nhưng giúp mình bớt kết luận vội. Ngoài đời cũng vậy — chuyện hay đôi khi bắt đầu từ một câu “kể thêm đi”.","media":{"type":"image","url":"./assets/photos/placement-11.webp","driveFileId":"1_--q_bu-X3QKB3BV1vardacER_recUPD","alt":"Về tôi 01","fit":"cover","position":"50% 50%"}},{"id":"translator","title":"Đổi ngôn ngữ, vẫn phải đúng ý.","period":"Góc nhìn demo · Ngôn ngữ × dữ liệu × thiết kế","summary":"Một bài nghiên cứu, một dashboard và một landing page phục vụ những người đọc khác nhau. Mình thích tìm cách diễn đạt phù hợp với từng người: thuật ngữ khi cần chính xác, lời giải thích khi cần làm rõ. Tiếng Việt hay tiếng Anh đều phải đúng ngữ pháp, đúng sắc thái và hợp hoàn cảnh. “Could you…?” là lời nhờ; sang tiếng Việt, một chữ “giúp” đôi khi tự nhiên hơn cả một câu dịch sát.","media":{"type":"image","url":"./assets/photos/placement-12.webp","driveFileId":"1nMvVmdOaznzks5OpfLH189TTw1A93r4T","alt":"Về tôi 02","fit":"cover","position":"50% 50%"}},{"id":"impact","title":"Chuyện lớn, bắt đầu từ người thật.","period":"Góc nhìn demo · Đổi mới sáng tạo và phát triển bền vững","summary":"ESG, Net Zero hay AI nghe có vẻ ở tận đâu đâu. Mình muốn kéo chúng về những câu hỏi gần hơn: người học đang vướng gì, đội nhóm cần gì, người dùng được giúp ra sao? Ý tưởng hay cần có người hưởng lợi cụ thể. Big ideas, human scale — nghĩ rộng, rồi làm cho sát đời sống.","media":{"type":"image","url":"./assets/photos/placement-10.webp","driveFileId":"1vU0L6PXdk8OZnK93R1Vy7DGEcHxNOZtF","alt":"Về tôi 03","fit":"cover","position":"50% 72%"}},{"id":"everyday-curiosity","title":"Ra ngoài một chút, mang chuyện về một chút.","period":"Một góc đời thường","summary":"Có hôm mình tạm đóng các tab tài liệu để đi dạo, gặp bạn bè hoặc ngồi nhìn một góc phố. Không phải khoảnh khắc nào cũng cần thành một bài học. Nhưng những cuộc gặp và những chuyện nhỏ thường giúp mình hiểu người hơn — rồi mang sự tò mò ấy trở lại với việc học và công việc. Offline một chút, có khi lại kết nối được nhiều hơn.","media":{"type":"image","url":"./assets/photos/placement-09.webp","driveFileId":"1FC-fg21z1aUghu91WHnyRCoNIlJtDOUn","alt":"Về tôi 04","fit":"cover","position":"50% 58%"}}],"work":[{"id":"city-notes","projectId":"city-notes","title":"Ra phố hít thở, não vẫn hỏi “vì sao?”.","summary":"Định đi dạo cho đầu nhẹ chút, ai dè mang theo cả câu hỏi về thành phố. Một câu chuyện demo của chiếc Việt thích quan sát.","period":"Câu chuyện demo · Ảnh từ bộ sưu tập của Việt","media":{"type":"image","url":"./assets/photos/placement-17.webp","driveFileId":"1Q1DGyb6qIgPKuWsv_wjOWCKkQWwTgMLU","alt":"Ngoài lề 01","fit":"cover","position":"50% 50%"}},{"id":"two-languages","projectId":"two-languages","title":"Một ý tưởng, hai ngôn ngữ, vài lần sửa.","summary":"Tiếng Anh viết một kiểu, tiếng Việt lại cần một nhịp khác. Mình thử giữ đúng ý mà vẫn để câu chữ có giọng riêng — trong một câu chuyện demo.","period":"Câu chuyện demo · Ảnh từ bộ sưu tập của Việt","media":{"type":"image","url":"./assets/photos/placement-16.webp","driveFileId":"1ZcvoP02r19zBxPxUYIE-eioVMJgVjHG9","alt":"Ngoài lề 02","fit":"cover","position":"50% 50%"}},{"id":"small-scripts","projectId":"small-scripts","title":"Một việc lặp lại, một chiếc script cứu nguy.","summary":"Bảng tính hơi dài, thao tác hơi lặp. Trong câu chuyện demo này, mình rủ Python vào phụ một tay. Plot twist: máy cũng cần mình chỉ đúng.","period":"Câu chuyện demo · Ảnh từ bộ sưu tập của Việt","media":{"type":"image","url":"./assets/photos/placement-15.webp","driveFileId":"1eVv88p8L-u-uMPyvptBSy4_Q_Z16I1U1","alt":"Ngoài lề 03","fit":"cover","position":"50% 50%"}},{"id":"behind-sprint","projectId":"behind-sprint","title":"Sprint có deadline. Người thì có tâm trạng.","summary":"Một câu chuyện demo phía sau lịch họp và bảng tiến độ: đôi khi câu hỏi “bạn đang vướng gì?” có ích hơn một lời nhắc deadline.","period":"Câu chuyện demo · Ảnh từ bộ sưu tập của Việt","media":{"type":"image","url":"./assets/photos/placement-14.webp","driveFileId":"1zeZ1DGKnsYXFkXC0yYjnsqYp2kVhwt2q","alt":"Ngoài lề 04","fit":"cover","position":"50% 50%"}},{"id":"little-laughs","projectId":"little-laughs","title":"Cho phép mình hơi ngốc nghếch một xíu.","summary":"Một chú thỏ, một chiếc meme, một khoảng nghỉ. Chiếc Việt không phải lúc nào cũng bật research mode đâu nha.","period":"Câu chuyện demo · Ảnh từ bộ sưu tập của Việt","media":{"type":"image","url":"./assets/photos/placement-13.webp","driveFileId":"1b5Fcx4Bl0Iy_Tt8lpJyCgmk4hnPANa_q","alt":"Ngoài lề 05","fit":"cover","position":"50% 50%"}}]},"chapterMedia":{"school":{"type":"image","url":"./assets/photos/placement-18.webp","driveFileId":"1larMR3gtS7cJtfVCEa46o2dHl0Mqycvt","alt":"Trường học 01","fit":"cover","position":"50% 56%"},"personal":{"type":"image","url":"./assets/photos/placement-11.webp","driveFileId":"1_--q_bu-X3QKB3BV1vardacER_recUPD","alt":"Về tôi 01","fit":"cover","position":"50% 50%"},"experience":{"type":"image","url":"./assets/photos/placement-20.webp","driveFileId":"1rWRbpDXZivhzqZir8r70jcEgKAPrf3x9","alt":"Kinh nghiệm FIIS","fit":"cover","position":"50% 60%"},"life":{"type":"image","url":"./assets/photos/placement-17.webp","driveFileId":"1Q1DGyb6qIgPKuWsv_wjOWCKkQWwTgMLU","alt":"Ngoài lề 01","fit":"cover","position":"50% 50%"}},"heroMedia":{"type":"image","url":"./assets/photos/placement-21.webp","driveFileId":"1b7TUXNA22LUp5kSw7U9sHB-DEWrj_oPT","alt":"Ảnh bìa title","fit":"cover","position":"50% 50%"},"aboutGallery":[{"type":"image","url":"./assets/photos/placement-01.webp","driveFileId":"12qmMIDgFmxjy0Y0m-Ab9mzxr5wvcFmoi","alt":"Về tôi bonus","fit":"cover","position":"50% 55%"}],"contactMedia":{"type":"image","url":"./assets/photos/placement-03.webp","driveFileId":"1U5tMEMklDZorPU1UWfBBK5fWSKIknHHn","alt":"The next chapter","fit":"cover","position":"50% 75%"},"contactGallery":[{"type":"image","url":"./assets/photos/placement-05.webp","driveFileId":"1xyu2sufnwx1B5ZmvEDcpqANPgIEt66SL","alt":"The next chapter 01","fit":"cover","position":"50% 50%"},{"type":"image","url":"./assets/photos/placement-04.webp","driveFileId":"1kHEOU4uZ5FeIkIDozjtDEbhHWgRB2-Rf","alt":"Kết nối 01","fit":"cover","position":"50% 50%"}]};
